import java.util.*;
import java.io.*;

public class Main {
    static final int MOD = 1000000007;
    static final int INV = 570000004;
    static Map<BitSet, Integer> indexMap = new HashMap<>();
    static int nodeId, timeCounter;
    static int[][] childrenArray = new int[65536][128];
    static int[][] p = new int[7][7];
    static int[][] q = new int[7][128];
    static int[][] dp = new int[8][65536];

    static int addMod(int a, int b) {
        int res = a + b;
        return res >= MOD ? res - MOD : res;
    }

    static int subMod(int a, int b) {
        int res = a - b;
        return res < 0 ? res + MOD : res;
    }

    static int mulMod(int a, int b) {
        return (int)((1L * a * b) % MOD);
    }

    static int dfs(BitSet state) {
        if (indexMap.containsKey(state))
            return indexMap.get(state);
        int id = timeCounter++;
        indexMap.put((BitSet) state.clone(), id);
        for (int mask = 0; mask < (1 << nodeId); ++mask) {
            BitSet newState = (BitSet) state.clone();
            for (int j = 0; j < nodeId; ++j) {
                if (!newState.get(j)) {
                    int kMask = mask & (1 << j);
                    for (int k = kMask; k != 0; k &= k - 1) {
                        int kBit = Integer.numberOfTrailingZeros(k);
                        if (state.get(j ^ (1 << kBit))) {
                            newState.set(j);
                            break;
                        }
                    }
                }
            }
            childrenArray[id][mask] = dfs(newState);
        }
        return id;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        BitSet initialState = new BitSet();
        initialState.set(0);
        nodeId = 0;
        timeCounter = 0;
        indexMap.clear();
        dfs(initialState);
        for (int i = 0; i < n; ++i) {
            String[] line = br.readLine().split(" ");
            for (int j = 0; j < n; ++j) {
                p[i][j] = Integer.parseInt(line[j]);
                p[i][j] = mulMod(p[i][j], INV);
            }
        }
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < (1 << n); ++j) {
                q[i][j] = 1;
                for (int k = 0; k < n; ++k) {
                    int val = ((j >> k) & 1) != 0 ? p[k][i] : subMod(1, p[k][i]);
                    q[i][j] = mulMod(q[i][j], val);
                }
            }
        }
        for (int i = 0; i <= n; ++i)
            Arrays.fill(dp[i], 0);
        dp[0][0] = 1;
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < nodeId; ++j) {
                for (int k = 0; k < (1 << n); ++k) {
                    int nextState = childrenArray[j][k];
                    dp[i + 1][nextState] = addMod(dp[i + 1][nextState], mulMod(dp[i][j], q[i][k]));
                }
            }
        }
        BitSet res = new BitSet();
        res.set(0, 1 << n);
        int resIndex = indexMap.get(res);
        System.out.println(dp[n][resIndex]);
    }
}
